export function interpolateKnots(knots,s,column=1){let lo=0,hi=knots.length-1;if(s<=knots[0][0])return knots[0][column];if(s>=knots[hi][0])return knots[hi][column];while(hi-lo>1){const m=(lo+hi)>>1;if(knots[m][0]<=s)lo=m;else hi=m;}const a=knots[lo],b=knots[hi];return a[column]+(b[column]-a[column])*(s-a[0])/(b[0]-a[0]);}
export class TrackLayout {
 constructor(data){this.data=data;this.stations=data.stations;this.tracks=data.tracks;this.buckets=new Map();for(const track of this.tracks)for(let n=Math.floor(track.knots[0][0]/500);n<=Math.floor(track.knots.at(-1)[0]/500);n++){if(!this.buckets.has(n))this.buckets.set(n,[]);this.buckets.get(n).push(track);}}
 activeAt(s){const found=[];for(const track of this.buckets.get(Math.floor(s/500))??[]){if(s<track.knots[0][0]||s>track.knots.at(-1)[0])continue;const x=interpolateKnots(track.knots,s),y=interpolateKnots(track.knots,s,2);if(found.some(t=>Math.abs(t.x-x)<.18&&Math.abs(t.y-y)<.2))continue;found.push({track,x,y});}return found.sort((a,b)=>a.x-b.x);}
 bounds(platform,s){let left=interpolateKnots(platform.edges,s,1),right=interpolateKnots(platform.edges,s,2);const middle=(left+right)/2;for(const rail of this.activeAt(s)){if(rail.y>.5)continue;if(rail.x<=middle)left=Math.max(left,rail.x+1.5);else right=Math.min(right,rail.x-1.5);}return {left,right,width:Math.max(0,right-left),center:(left+right)/2};}
 occupied(s,x){if(this.activeAt(s).some(t=>Math.abs(t.x-x)<3.0))return true;for(const st of this.stations){if(s<st.s-450||s>st.s+300)continue;for(const platform of st.platforms)if(s>=platform.start-10&&s<=platform.end+10){const b=this.bounds(platform,s);if(x>=b.left-2&&x<=b.right+2)return true;}}return false;}
}
